// Vulkan 1.1 renderer with classic render passes (Android 10 devices support 1.1).
#include "midgard/render/renderer.h"

#include <algorithm>
#include <array>
#include <cstdlib>
#include <cstring>

#include <volk.h>
// volk must come first: it defines VK_NO_PROTOTYPES users and the function pointers VMA uses.
#include <vk_mem_alloc.h>

#include <glm/gtc/matrix_transform.hpp>

#include "mesh_frag.h"  // generated by glslangValidator at build time
#include "mesh_vert.h"
#include "overlay_frag.h"
#include "overlay_vert.h"

namespace midgard::render {
namespace {

constexpr uint32_t kFramesInFlight = 2;

void check(VkResult result, const char* what) {
    if (result != VK_SUCCESS)
        throw RenderError(std::string(what) + " failed (VkResult " + std::to_string(result) + ")");
}

struct FrameData {
    glm::mat4 view_proj;
    glm::vec4 light_dir;
    glm::vec4 light_color;
    glm::vec4 ambient;
};

struct PushData {
    glm::mat4 model;
    glm::vec4 color;
};

// Colours arrive as designers pick them (sRGB). Lighting maths and the sRGB framebuffer
// expect linear values, so convert once here; alpha is already linear.
glm::vec3 to_linear(const glm::vec3& srgb) {
    return glm::pow(glm::clamp(srgb, 0.0f, 1.0f), glm::vec3(2.2f));
}
glm::vec4 to_linear(const glm::vec4& srgb) {
    return glm::vec4(to_linear(glm::vec3(srgb)), srgb.a);
}

struct Buffer {
    VkBuffer buffer = VK_NULL_HANDLE;
    VmaAllocation allocation = nullptr;
    void* mapped = nullptr;
};

struct Image {
    VkImage image = VK_NULL_HANDLE;
    VmaAllocation allocation = nullptr;
    VkImageView view = VK_NULL_HANDLE;
};

struct GpuMesh {
    Buffer vertices;
    Buffer indices;
    uint32_t index_count = 0;
};

}  // namespace

struct Renderer::Impl {
    bool offscreen = false;
    VkInstance instance = VK_NULL_HANDLE;
    VkSurfaceKHR surface = VK_NULL_HANDLE;
    std::function<VkSurfaceKHR_T*(VkInstance_T*)> create_surface;
    VkPhysicalDevice gpu = VK_NULL_HANDLE;
    VkPhysicalDeviceProperties gpu_props{};
    VkDevice device = VK_NULL_HANDLE;
    uint32_t queue_family = 0;
    VkQueue queue = VK_NULL_HANDLE;
    VmaAllocator allocator = nullptr;

    VkExtent2D extent{};
    VkFormat color_format = VK_FORMAT_UNDEFINED;
    VkFormat depth_format = VK_FORMAT_UNDEFINED;
    VkRenderPass render_pass = VK_NULL_HANDLE;

    // Window target
    VkSwapchainKHR swapchain = VK_NULL_HANDLE;
    std::vector<VkImage> swap_images;
    std::vector<VkImageView> swap_views;
    std::vector<VkSemaphore> render_done;  // one per swapchain image
    // Offscreen target
    Image offscreen_color;
    Buffer readback;
    // Shared
    Image depth;
    std::vector<VkFramebuffer> framebuffers;

    VkDescriptorSetLayout set_layout = VK_NULL_HANDLE;
    VkPipelineLayout pipeline_layout = VK_NULL_HANDLE;
    VkPipeline pipeline = VK_NULL_HANDLE;
    VkPipelineLayout overlay_layout = VK_NULL_HANDLE;
    VkPipeline overlay_pipeline = VK_NULL_HANDLE;
    std::vector<OverlayLine> overlay_lines;
    VkDescriptorPool descriptor_pool = VK_NULL_HANDLE;
    VkCommandPool command_pool = VK_NULL_HANDLE;

    struct Frame {
        VkCommandBuffer cmd = VK_NULL_HANDLE;
        VkFence fence = VK_NULL_HANDLE;
        VkSemaphore image_ready = VK_NULL_HANDLE;
        Buffer ubo;
        VkDescriptorSet set = VK_NULL_HANDLE;
        Buffer overlay;  // the overlay's triangles, rewritten each frame
        VkDeviceSize overlay_capacity = 0;
        uint32_t overlay_vertices = 0;
    };
    std::array<Frame, kFramesInFlight> frames{};
    uint32_t frame_index = 0;
    std::vector<GpuMesh> meshes;

    // ---- setup -------------------------------------------------------------------------
    void create_instance(const RendererDesc& desc) {
        check(volkInitialize(), "Loading the Vulkan library (is a Vulkan driver installed?)");
        VkApplicationInfo app{VK_STRUCTURE_TYPE_APPLICATION_INFO};
        app.pApplicationName = "Midgard";
        app.pEngineName = "Midgard";
        app.apiVersion = VK_API_VERSION_1_1;

        std::vector<const char*> layers;
        if (desc.validation) {
            uint32_t count = 0;
            vkEnumerateInstanceLayerProperties(&count, nullptr);
            std::vector<VkLayerProperties> available(count);
            vkEnumerateInstanceLayerProperties(&count, available.data());
            for (const auto& l : available)
                if (std::strcmp(l.layerName, "VK_LAYER_KHRONOS_validation") == 0)
                    layers.push_back("VK_LAYER_KHRONOS_validation");
        }
        VkInstanceCreateInfo info{VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO};
        info.pApplicationInfo = &app;
        info.enabledExtensionCount = static_cast<uint32_t>(desc.instance_extensions.size());
        info.ppEnabledExtensionNames = desc.instance_extensions.data();
        info.enabledLayerCount = static_cast<uint32_t>(layers.size());
        info.ppEnabledLayerNames = layers.data();
        check(vkCreateInstance(&info, nullptr, &instance), "Creating the Vulkan instance");
        volkLoadInstance(instance);
    }

    void pick_device() {
        uint32_t count = 0;
        vkEnumeratePhysicalDevices(instance, &count, nullptr);
        if (count == 0) throw RenderError("No Vulkan device found");
        std::vector<VkPhysicalDevice> devices(count);
        vkEnumeratePhysicalDevices(instance, &count, devices.data());

        int best_score = -1;
        for (VkPhysicalDevice d : devices) {
            VkPhysicalDeviceProperties props;
            vkGetPhysicalDeviceProperties(d, &props);
            uint32_t qcount = 0;
            vkGetPhysicalDeviceQueueFamilyProperties(d, &qcount, nullptr);
            std::vector<VkQueueFamilyProperties> families(qcount);
            vkGetPhysicalDeviceQueueFamilyProperties(d, &qcount, families.data());
            for (uint32_t q = 0; q < qcount; ++q) {
                if (!(families[q].queueFlags & VK_QUEUE_GRAPHICS_BIT)) continue;
                if (surface) {
                    VkBool32 present = VK_FALSE;
                    vkGetPhysicalDeviceSurfaceSupportKHR(d, q, surface, &present);
                    if (!present) continue;
                }
                const int score = props.deviceType == VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU     ? 3
                                  : props.deviceType == VK_PHYSICAL_DEVICE_TYPE_INTEGRATED_GPU ? 2
                                                                                               : 1;
                if (score > best_score) {
                    best_score = score;
                    gpu = d;
                    gpu_props = props;
                    queue_family = q;
                }
                break;
            }
        }
        if (!gpu) throw RenderError("No Vulkan device can draw to this target");
    }

    void create_device() {
        const float priority = 1.0f;
        VkDeviceQueueCreateInfo qinfo{VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO};
        qinfo.queueFamilyIndex = queue_family;
        qinfo.queueCount = 1;
        qinfo.pQueuePriorities = &priority;
        std::vector<const char*> extensions;
        if (!offscreen) extensions.push_back(VK_KHR_SWAPCHAIN_EXTENSION_NAME);
        VkDeviceCreateInfo info{VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO};
        info.queueCreateInfoCount = 1;
        info.pQueueCreateInfos = &qinfo;
        info.enabledExtensionCount = static_cast<uint32_t>(extensions.size());
        info.ppEnabledExtensionNames = extensions.data();
        check(vkCreateDevice(gpu, &info, nullptr, &device), "Creating the Vulkan device");
        volkLoadDevice(device);
        vkGetDeviceQueue(device, queue_family, 0, &queue);

        VmaVulkanFunctions functions{};
        functions.vkGetInstanceProcAddr = vkGetInstanceProcAddr;
        functions.vkGetDeviceProcAddr = vkGetDeviceProcAddr;
        VmaAllocatorCreateInfo ainfo{};
        ainfo.vulkanApiVersion = VK_API_VERSION_1_1;
        ainfo.physicalDevice = gpu;
        ainfo.device = device;
        ainfo.instance = instance;
        ainfo.pVulkanFunctions = &functions;
        check(vmaCreateAllocator(&ainfo, &allocator), "Creating the memory allocator");
    }

    VkFormat pick_depth_format() const {
        for (VkFormat f :
             {VK_FORMAT_D32_SFLOAT, VK_FORMAT_D24_UNORM_S8_UINT, VK_FORMAT_D16_UNORM}) {
            VkFormatProperties props;
            vkGetPhysicalDeviceFormatProperties(gpu, f, &props);
            if (props.optimalTilingFeatures & VK_FORMAT_FEATURE_DEPTH_STENCIL_ATTACHMENT_BIT)
                return f;
        }
        throw RenderError("No supported depth format");
    }

    Buffer create_buffer(VkDeviceSize size, VkBufferUsageFlags usage, bool host_readable) {
        VkBufferCreateInfo binfo{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};
        binfo.size = size;
        binfo.usage = usage;
        VmaAllocationCreateInfo ainfo{};
        ainfo.usage = VMA_MEMORY_USAGE_AUTO;
        ainfo.flags = VMA_ALLOCATION_CREATE_MAPPED_BIT |
                      (host_readable ? VMA_ALLOCATION_CREATE_HOST_ACCESS_RANDOM_BIT
                                     : VMA_ALLOCATION_CREATE_HOST_ACCESS_SEQUENTIAL_WRITE_BIT);
        Buffer b;
        VmaAllocationInfo info{};
        check(vmaCreateBuffer(allocator, &binfo, &ainfo, &b.buffer, &b.allocation, &info),
              "Creating a buffer");
        b.mapped = info.pMappedData;
        return b;
    }

    void destroy_buffer(Buffer& b) {
        if (b.buffer) vmaDestroyBuffer(allocator, b.buffer, b.allocation);
        b = {};
    }

    Image create_image(VkFormat format, VkImageUsageFlags usage, VkImageAspectFlags aspect) {
        VkImageCreateInfo iinfo{VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO};
        iinfo.imageType = VK_IMAGE_TYPE_2D;
        iinfo.format = format;
        iinfo.extent = {extent.width, extent.height, 1};
        iinfo.mipLevels = 1;
        iinfo.arrayLayers = 1;
        iinfo.samples = VK_SAMPLE_COUNT_1_BIT;
        iinfo.tiling = VK_IMAGE_TILING_OPTIMAL;
        iinfo.usage = usage;
        VmaAllocationCreateInfo ainfo{};
        ainfo.usage = VMA_MEMORY_USAGE_AUTO;
        Image img;
        check(vmaCreateImage(allocator, &iinfo, &ainfo, &img.image, &img.allocation, nullptr),
              "Creating an image");
        img.view = create_view(img.image, format, aspect);
        return img;
    }

    void destroy_image(Image& img) {
        if (img.view) vkDestroyImageView(device, img.view, nullptr);
        if (img.image) vmaDestroyImage(allocator, img.image, img.allocation);
        img = {};
    }

    VkImageView create_view(VkImage image, VkFormat format, VkImageAspectFlags aspect) {
        VkImageViewCreateInfo vinfo{VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};
        vinfo.image = image;
        vinfo.viewType = VK_IMAGE_VIEW_TYPE_2D;
        vinfo.format = format;
        vinfo.subresourceRange = {aspect, 0, 1, 0, 1};
        VkImageView view;
        check(vkCreateImageView(device, &vinfo, nullptr, &view), "Creating an image view");
        return view;
    }

    void choose_swapchain_format() {
        uint32_t count = 0;
        vkGetPhysicalDeviceSurfaceFormatsKHR(gpu, surface, &count, nullptr);
        std::vector<VkSurfaceFormatKHR> formats(count);
        vkGetPhysicalDeviceSurfaceFormatsKHR(gpu, surface, &count, formats.data());
        color_format = formats.at(0).format;
        for (const auto& f : formats)
            if ((f.format == VK_FORMAT_B8G8R8A8_SRGB || f.format == VK_FORMAT_R8G8B8A8_SRGB) &&
                f.colorSpace == VK_COLOR_SPACE_SRGB_NONLINEAR_KHR) {
                color_format = f.format;
                break;
            }
    }

    void create_render_pass() {
        std::array<VkAttachmentDescription, 2> attachments{};
        attachments[0].format = color_format;
        attachments[0].samples = VK_SAMPLE_COUNT_1_BIT;
        attachments[0].loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR;
        attachments[0].storeOp = VK_ATTACHMENT_STORE_OP_STORE;
        attachments[0].stencilLoadOp = VK_ATTACHMENT_LOAD_OP_DONT_CARE;
        attachments[0].stencilStoreOp = VK_ATTACHMENT_STORE_OP_DONT_CARE;
        attachments[0].initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
        attachments[0].finalLayout =
            offscreen ? VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL : VK_IMAGE_LAYOUT_PRESENT_SRC_KHR;
        attachments[1].format = depth_format;
        attachments[1].samples = VK_SAMPLE_COUNT_1_BIT;
        attachments[1].loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR;
        attachments[1].storeOp = VK_ATTACHMENT_STORE_OP_DONT_CARE;
        attachments[1].stencilLoadOp = VK_ATTACHMENT_LOAD_OP_DONT_CARE;
        attachments[1].stencilStoreOp = VK_ATTACHMENT_STORE_OP_DONT_CARE;
        attachments[1].initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
        attachments[1].finalLayout = VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL;

        VkAttachmentReference color_ref{0, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL};
        VkAttachmentReference depth_ref{1, VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL};
        VkSubpassDescription subpass{};
        subpass.pipelineBindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
        subpass.colorAttachmentCount = 1;
        subpass.pColorAttachments = &color_ref;
        subpass.pDepthStencilAttachment = &depth_ref;

        VkSubpassDependency dep{};
        dep.srcSubpass = VK_SUBPASS_EXTERNAL;
        dep.dstSubpass = 0;
        dep.srcStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT |
                           VK_PIPELINE_STAGE_LATE_FRAGMENT_TESTS_BIT;
        dep.dstStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT |
                           VK_PIPELINE_STAGE_EARLY_FRAGMENT_TESTS_BIT;
        dep.srcAccessMask = VK_ACCESS_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT;
        dep.dstAccessMask =
            VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT | VK_ACCESS_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT;

        VkRenderPassCreateInfo info{VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO};
        info.attachmentCount = static_cast<uint32_t>(attachments.size());
        info.pAttachments = attachments.data();
        info.subpassCount = 1;
        info.pSubpasses = &subpass;
        info.dependencyCount = 1;
        info.pDependencies = &dep;
        check(vkCreateRenderPass(device, &info, nullptr, &render_pass), "Creating the render pass");
    }

    // ---- size-dependent resources --------------------------------------------------------
    void create_target() {
        std::vector<VkImageView> color_views;
        if (offscreen) {
            offscreen_color = create_image(
                color_format, VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT | VK_IMAGE_USAGE_TRANSFER_SRC_BIT,
                VK_IMAGE_ASPECT_COLOR_BIT);
            readback = create_buffer(VkDeviceSize(extent.width) * extent.height * 4,
                                     VK_BUFFER_USAGE_TRANSFER_DST_BIT, true);
            color_views.push_back(offscreen_color.view);
        } else {
            VkSurfaceCapabilitiesKHR caps;
            vkGetPhysicalDeviceSurfaceCapabilitiesKHR(gpu, surface, &caps);
            if (caps.currentExtent.width != UINT32_MAX) extent = caps.currentExtent;
            extent.width =
                std::clamp(extent.width, caps.minImageExtent.width, caps.maxImageExtent.width);
            extent.height =
                std::clamp(extent.height, caps.minImageExtent.height, caps.maxImageExtent.height);
            uint32_t count = caps.minImageCount + 1;
            if (caps.maxImageCount > 0) count = std::min(count, caps.maxImageCount);

            VkSwapchainCreateInfoKHR info{VK_STRUCTURE_TYPE_SWAPCHAIN_CREATE_INFO_KHR};
            info.surface = surface;
            info.minImageCount = count;
            info.imageFormat = color_format;
            info.imageColorSpace = VK_COLOR_SPACE_SRGB_NONLINEAR_KHR;
            info.imageExtent = extent;
            info.imageArrayLayers = 1;
            info.imageUsage = VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT;
            info.imageSharingMode = VK_SHARING_MODE_EXCLUSIVE;
            // Identity lets the compositor rotate the image on phones held in landscape
            // (pre-rotating in the renderer is an optimisation for later).
            info.preTransform = (caps.supportedTransforms & VK_SURFACE_TRANSFORM_IDENTITY_BIT_KHR)
                                    ? VK_SURFACE_TRANSFORM_IDENTITY_BIT_KHR
                                    : caps.currentTransform;
            info.compositeAlpha = (caps.supportedCompositeAlpha & VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR)
                                      ? VK_COMPOSITE_ALPHA_OPAQUE_BIT_KHR
                                      : VK_COMPOSITE_ALPHA_INHERIT_BIT_KHR;
            info.presentMode = VK_PRESENT_MODE_FIFO_KHR;  // always supported; vsync
            info.clipped = VK_TRUE;
            check(vkCreateSwapchainKHR(device, &info, nullptr, &swapchain),
                  "Creating the swapchain");
            vkGetSwapchainImagesKHR(device, swapchain, &count, nullptr);
            swap_images.resize(count);
            vkGetSwapchainImagesKHR(device, swapchain, &count, swap_images.data());
            for (VkImage img : swap_images) {
                swap_views.push_back(create_view(img, color_format, VK_IMAGE_ASPECT_COLOR_BIT));
                VkSemaphoreCreateInfo sinfo{VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO};
                VkSemaphore sem;
                check(vkCreateSemaphore(device, &sinfo, nullptr, &sem), "Creating a semaphore");
                render_done.push_back(sem);
            }
            color_views = swap_views;
        }
        depth = create_image(depth_format, VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT,
                             VK_IMAGE_ASPECT_DEPTH_BIT);
        for (VkImageView color : color_views) {
            std::array<VkImageView, 2> views{color, depth.view};
            VkFramebufferCreateInfo finfo{VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO};
            finfo.renderPass = render_pass;
            finfo.attachmentCount = static_cast<uint32_t>(views.size());
            finfo.pAttachments = views.data();
            finfo.width = extent.width;
            finfo.height = extent.height;
            finfo.layers = 1;
            VkFramebuffer fb;
            check(vkCreateFramebuffer(device, &finfo, nullptr, &fb), "Creating a framebuffer");
            framebuffers.push_back(fb);
        }
    }

    void destroy_target() {
        for (VkFramebuffer fb : framebuffers) vkDestroyFramebuffer(device, fb, nullptr);
        framebuffers.clear();
        destroy_image(depth);
        destroy_image(offscreen_color);
        destroy_buffer(readback);
        for (VkImageView v : swap_views) vkDestroyImageView(device, v, nullptr);
        swap_views.clear();
        for (VkSemaphore s : render_done) vkDestroySemaphore(device, s, nullptr);
        render_done.clear();
        swap_images.clear();
        if (swapchain) vkDestroySwapchainKHR(device, swapchain, nullptr);
        swapchain = VK_NULL_HANDLE;
    }

    void recreate_target() {
        vkDeviceWaitIdle(device);
        destroy_target();
        create_target();
    }

    // The window system replaced the window's surface (Android, after returning from the
    // background).
    void recreate_surface() {
        vkDeviceWaitIdle(device);
        destroy_target();
        vkDestroySurfaceKHR(instance, surface, nullptr);
        surface = reinterpret_cast<VkSurfaceKHR>(
            create_surface(reinterpret_cast<VkInstance_T*>(instance)));
        if (!surface) throw RenderError("Recreating the window surface failed");
        create_target();
    }

    // ---- pipeline and per-frame data ---------------------------------------------------
    VkShaderModule shader(const uint32_t* code, size_t bytes) {
        VkShaderModuleCreateInfo info{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};
        info.codeSize = bytes;
        info.pCode = code;
        VkShaderModule module;
        check(vkCreateShaderModule(device, &info, nullptr, &module), "Creating a shader module");
        return module;
    }

    void create_pipeline() {
        VkDescriptorSetLayoutBinding binding{};
        binding.binding = 0;
        binding.descriptorType = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
        binding.descriptorCount = 1;
        binding.stageFlags = VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT;
        VkDescriptorSetLayoutCreateInfo linfo{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};
        linfo.bindingCount = 1;
        linfo.pBindings = &binding;
        check(vkCreateDescriptorSetLayout(device, &linfo, nullptr, &set_layout),
              "Creating the descriptor set layout");

        VkPushConstantRange push{VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0,
                                 sizeof(PushData)};
        VkPipelineLayoutCreateInfo plinfo{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
        plinfo.setLayoutCount = 1;
        plinfo.pSetLayouts = &set_layout;
        plinfo.pushConstantRangeCount = 1;
        plinfo.pPushConstantRanges = &push;
        check(vkCreatePipelineLayout(device, &plinfo, nullptr, &pipeline_layout),
              "Creating the pipeline layout");

        VkShaderModule vert = shader(mesh_vert, sizeof(mesh_vert));
        VkShaderModule frag = shader(mesh_frag, sizeof(mesh_frag));
        std::array<VkPipelineShaderStageCreateInfo, 2> stages{};
        stages[0] = {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO};
        stages[0].stage = VK_SHADER_STAGE_VERTEX_BIT;
        stages[0].module = vert;
        stages[0].pName = "main";
        stages[1] = {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO};
        stages[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT;
        stages[1].module = frag;
        stages[1].pName = "main";

        VkVertexInputBindingDescription vbind{0, sizeof(Vertex), VK_VERTEX_INPUT_RATE_VERTEX};
        std::array<VkVertexInputAttributeDescription, 2> attrs{{
            {0, 0, VK_FORMAT_R32G32B32_SFLOAT, offsetof(Vertex, position)},
            {1, 0, VK_FORMAT_R32G32B32_SFLOAT, offsetof(Vertex, normal)},
        }};
        VkPipelineVertexInputStateCreateInfo vinput{
            VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO};
        vinput.vertexBindingDescriptionCount = 1;
        vinput.pVertexBindingDescriptions = &vbind;
        vinput.vertexAttributeDescriptionCount = static_cast<uint32_t>(attrs.size());
        vinput.pVertexAttributeDescriptions = attrs.data();

        VkPipelineInputAssemblyStateCreateInfo assembly{
            VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO};
        assembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
        VkPipelineViewportStateCreateInfo viewport{
            VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO};
        viewport.viewportCount = 1;
        viewport.scissorCount = 1;
        VkPipelineRasterizationStateCreateInfo raster{
            VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO};
        raster.polygonMode = VK_POLYGON_MODE_FILL;
        raster.cullMode = VK_CULL_MODE_BACK_BIT;
        raster.frontFace = VK_FRONT_FACE_COUNTER_CLOCKWISE;  // with the y-flipped projection
        raster.lineWidth = 1.0f;
        VkPipelineMultisampleStateCreateInfo multisample{
            VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO};
        multisample.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;
        VkPipelineDepthStencilStateCreateInfo depth_state{
            VK_STRUCTURE_TYPE_PIPELINE_DEPTH_STENCIL_STATE_CREATE_INFO};
        depth_state.depthTestEnable = VK_TRUE;
        depth_state.depthWriteEnable = VK_TRUE;
        depth_state.depthCompareOp = VK_COMPARE_OP_LESS;
        VkPipelineColorBlendAttachmentState blend_att{};
        blend_att.colorWriteMask = VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT |
                                   VK_COLOR_COMPONENT_B_BIT | VK_COLOR_COMPONENT_A_BIT;
        VkPipelineColorBlendStateCreateInfo blend{
            VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO};
        blend.attachmentCount = 1;
        blend.pAttachments = &blend_att;
        std::array<VkDynamicState, 2> dyn{VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
        VkPipelineDynamicStateCreateInfo dynamic{
            VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO};
        dynamic.dynamicStateCount = static_cast<uint32_t>(dyn.size());
        dynamic.pDynamicStates = dyn.data();

        VkGraphicsPipelineCreateInfo info{VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO};
        info.stageCount = static_cast<uint32_t>(stages.size());
        info.pStages = stages.data();
        info.pVertexInputState = &vinput;
        info.pInputAssemblyState = &assembly;
        info.pViewportState = &viewport;
        info.pRasterizationState = &raster;
        info.pMultisampleState = &multisample;
        info.pDepthStencilState = &depth_state;
        info.pColorBlendState = &blend;
        info.pDynamicState = &dynamic;
        info.layout = pipeline_layout;
        info.renderPass = render_pass;
        const VkResult result =
            vkCreateGraphicsPipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
        vkDestroyShaderModule(device, vert, nullptr);
        vkDestroyShaderModule(device, frag, nullptr);
        check(result, "Creating the graphics pipeline");
    }

    // The overlay: alpha-blended 2D triangles over everything, no depth test.
    void create_overlay_pipeline() {
        VkPushConstantRange push{VK_SHADER_STAGE_VERTEX_BIT, 0, sizeof(glm::vec2)};
        VkPipelineLayoutCreateInfo plinfo{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
        plinfo.pushConstantRangeCount = 1;
        plinfo.pPushConstantRanges = &push;
        check(vkCreatePipelineLayout(device, &plinfo, nullptr, &overlay_layout),
              "Creating the overlay pipeline layout");

        VkShaderModule vert = shader(overlay_vert, sizeof(overlay_vert));
        VkShaderModule frag = shader(overlay_frag, sizeof(overlay_frag));
        std::array<VkPipelineShaderStageCreateInfo, 2> stages{};
        stages[0] = {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO};
        stages[0].stage = VK_SHADER_STAGE_VERTEX_BIT;
        stages[0].module = vert;
        stages[0].pName = "main";
        stages[1] = {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO};
        stages[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT;
        stages[1].module = frag;
        stages[1].pName = "main";

        VkVertexInputBindingDescription vbind{0, sizeof(OverlayVertex),
                                              VK_VERTEX_INPUT_RATE_VERTEX};
        std::array<VkVertexInputAttributeDescription, 2> attrs{{
            {0, 0, VK_FORMAT_R32G32_SFLOAT, offsetof(OverlayVertex, position)},
            {1, 0, VK_FORMAT_R32G32B32A32_SFLOAT, offsetof(OverlayVertex, color)},
        }};
        VkPipelineVertexInputStateCreateInfo vinput{
            VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO};
        vinput.vertexBindingDescriptionCount = 1;
        vinput.pVertexBindingDescriptions = &vbind;
        vinput.vertexAttributeDescriptionCount = static_cast<uint32_t>(attrs.size());
        vinput.pVertexAttributeDescriptions = attrs.data();
        VkPipelineInputAssemblyStateCreateInfo assembly{
            VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO};
        assembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
        VkPipelineViewportStateCreateInfo viewport{
            VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO};
        viewport.viewportCount = 1;
        viewport.scissorCount = 1;
        VkPipelineRasterizationStateCreateInfo raster{
            VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO};
        raster.polygonMode = VK_POLYGON_MODE_FILL;
        raster.cullMode = VK_CULL_MODE_NONE;
        raster.lineWidth = 1.0f;
        VkPipelineMultisampleStateCreateInfo multisample{
            VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO};
        multisample.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;
        VkPipelineDepthStencilStateCreateInfo depth_state{
            VK_STRUCTURE_TYPE_PIPELINE_DEPTH_STENCIL_STATE_CREATE_INFO};
        VkPipelineColorBlendAttachmentState blend_att{};
        blend_att.blendEnable = VK_TRUE;
        blend_att.srcColorBlendFactor = VK_BLEND_FACTOR_SRC_ALPHA;
        blend_att.dstColorBlendFactor = VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;
        blend_att.colorBlendOp = VK_BLEND_OP_ADD;
        blend_att.srcAlphaBlendFactor = VK_BLEND_FACTOR_ONE;
        blend_att.dstAlphaBlendFactor = VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;
        blend_att.alphaBlendOp = VK_BLEND_OP_ADD;
        blend_att.colorWriteMask = VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT |
                                   VK_COLOR_COMPONENT_B_BIT | VK_COLOR_COMPONENT_A_BIT;
        VkPipelineColorBlendStateCreateInfo blend{
            VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO};
        blend.attachmentCount = 1;
        blend.pAttachments = &blend_att;
        std::array<VkDynamicState, 2> dyn{VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
        VkPipelineDynamicStateCreateInfo dynamic{
            VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO};
        dynamic.dynamicStateCount = static_cast<uint32_t>(dyn.size());
        dynamic.pDynamicStates = dyn.data();

        VkGraphicsPipelineCreateInfo info{VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO};
        info.stageCount = static_cast<uint32_t>(stages.size());
        info.pStages = stages.data();
        info.pVertexInputState = &vinput;
        info.pInputAssemblyState = &assembly;
        info.pViewportState = &viewport;
        info.pRasterizationState = &raster;
        info.pMultisampleState = &multisample;
        info.pDepthStencilState = &depth_state;
        info.pColorBlendState = &blend;
        info.pDynamicState = &dynamic;
        info.layout = overlay_layout;
        info.renderPass = render_pass;
        const VkResult result =
            vkCreateGraphicsPipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &overlay_pipeline);
        vkDestroyShaderModule(device, vert, nullptr);
        vkDestroyShaderModule(device, frag, nullptr);
        check(result, "Creating the overlay pipeline");
    }

    // Lays out the overlay for this frame into the frame's own vertex buffer.
    void prepare_overlay(Frame& f) {
        f.overlay_vertices = 0;
        if (overlay_lines.empty()) return;
        const std::vector<OverlayVertex> vertices =
            layout_overlay(overlay_lines, extent.width, extent.height);
        const VkDeviceSize bytes = vertices.size() * sizeof(OverlayVertex);
        if (bytes == 0) return;
        if (bytes > f.overlay_capacity) {  // the fence has passed, so the old one is unused
            destroy_buffer(f.overlay);
            f.overlay_capacity = std::max<VkDeviceSize>(bytes * 2, 64 * 1024);
            f.overlay = create_buffer(f.overlay_capacity, VK_BUFFER_USAGE_VERTEX_BUFFER_BIT, false);
        }
        std::memcpy(f.overlay.mapped, vertices.data(), bytes);
        vmaFlushAllocation(allocator, f.overlay.allocation, 0, bytes);
        f.overlay_vertices = static_cast<uint32_t>(vertices.size());
    }

    void create_frames() {
        VkCommandPoolCreateInfo cinfo{VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};
        cinfo.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
        cinfo.queueFamilyIndex = queue_family;
        check(vkCreateCommandPool(device, &cinfo, nullptr, &command_pool),
              "Creating the command pool");

        VkDescriptorPoolSize size{VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, kFramesInFlight};
        VkDescriptorPoolCreateInfo pinfo{VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO};
        pinfo.maxSets = kFramesInFlight;
        pinfo.poolSizeCount = 1;
        pinfo.pPoolSizes = &size;
        check(vkCreateDescriptorPool(device, &pinfo, nullptr, &descriptor_pool),
              "Creating the descriptor pool");

        for (Frame& f : frames) {
            VkCommandBufferAllocateInfo ainfo{VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};
            ainfo.commandPool = command_pool;
            ainfo.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
            ainfo.commandBufferCount = 1;
            check(vkAllocateCommandBuffers(device, &ainfo, &f.cmd), "Allocating a command buffer");
            VkFenceCreateInfo finfo{VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};
            finfo.flags = VK_FENCE_CREATE_SIGNALED_BIT;
            check(vkCreateFence(device, &finfo, nullptr, &f.fence), "Creating a fence");
            VkSemaphoreCreateInfo sinfo{VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO};
            check(vkCreateSemaphore(device, &sinfo, nullptr, &f.image_ready),
                  "Creating a semaphore");
            f.ubo = create_buffer(sizeof(FrameData), VK_BUFFER_USAGE_UNIFORM_BUFFER_BIT, false);

            VkDescriptorSetAllocateInfo dinfo{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};
            dinfo.descriptorPool = descriptor_pool;
            dinfo.descriptorSetCount = 1;
            dinfo.pSetLayouts = &set_layout;
            check(vkAllocateDescriptorSets(device, &dinfo, &f.set), "Allocating a descriptor set");
            VkDescriptorBufferInfo binfo{f.ubo.buffer, 0, sizeof(FrameData)};
            VkWriteDescriptorSet write{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
            write.dstSet = f.set;
            write.dstBinding = 0;
            write.descriptorCount = 1;
            write.descriptorType = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
            write.pBufferInfo = &binfo;
            vkUpdateDescriptorSets(device, 1, &write, 0, nullptr);
        }
    }

    // ---- drawing -----------------------------------------------------------------------
    void record(VkCommandBuffer cmd, VkFramebuffer fb, const std::span<const DrawItem> draws,
                const glm::vec4& clear_color, VkDescriptorSet set, const Frame& frame) {
        VkCommandBufferBeginInfo begin{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
        begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
        check(vkBeginCommandBuffer(cmd, &begin), "Beginning a command buffer");
        std::array<VkClearValue, 2> clears{};
        const glm::vec4 clear = to_linear(clear_color);
        clears[0].color = {{clear.r, clear.g, clear.b, clear.a}};
        clears[1].depthStencil = {1.0f, 0};
        VkRenderPassBeginInfo rp{VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO};
        rp.renderPass = render_pass;
        rp.framebuffer = fb;
        rp.renderArea = {{0, 0}, extent};
        rp.clearValueCount = static_cast<uint32_t>(clears.size());
        rp.pClearValues = clears.data();
        vkCmdBeginRenderPass(cmd, &rp, VK_SUBPASS_CONTENTS_INLINE);
        VkViewport vp{0, 0, float(extent.width), float(extent.height), 0.0f, 1.0f};
        VkRect2D scissor{{0, 0}, extent};
        vkCmdSetViewport(cmd, 0, 1, &vp);
        vkCmdSetScissor(cmd, 0, 1, &scissor);
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, pipeline);
        vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, pipeline_layout, 0, 1, &set,
                                0, nullptr);
        for (const DrawItem& d : draws) {
            if (d.mesh >= meshes.size()) continue;
            const GpuMesh& m = meshes[d.mesh];
            PushData push{d.model, to_linear(d.color)};
            vkCmdPushConstants(cmd, pipeline_layout,
                               VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0,
                               sizeof(push), &push);
            VkDeviceSize offset = 0;
            vkCmdBindVertexBuffers(cmd, 0, 1, &m.vertices.buffer, &offset);
            vkCmdBindIndexBuffer(cmd, m.indices.buffer, 0, VK_INDEX_TYPE_UINT32);
            vkCmdDrawIndexed(cmd, m.index_count, 1, 0, 0, 0);
        }
        if (frame.overlay_vertices > 0) {
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, overlay_pipeline);
            const glm::vec2 screen(float(extent.width), float(extent.height));
            vkCmdPushConstants(cmd, overlay_layout, VK_SHADER_STAGE_VERTEX_BIT, 0, sizeof(screen),
                               &screen);
            VkDeviceSize offset = 0;
            vkCmdBindVertexBuffers(cmd, 0, 1, &frame.overlay.buffer, &offset);
            vkCmdDraw(cmd, frame.overlay_vertices, 1, 0, 0);
        }
        vkCmdEndRenderPass(cmd);
        if (offscreen) {
            VkBufferImageCopy copy{};
            copy.imageSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1};
            copy.imageExtent = {extent.width, extent.height, 1};
            vkCmdCopyImageToBuffer(cmd, offscreen_color.image, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                                   readback.buffer, 1, &copy);
            VkBufferMemoryBarrier barrier{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER};
            barrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
            barrier.dstAccessMask = VK_ACCESS_HOST_READ_BIT;
            barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
            barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
            barrier.buffer = readback.buffer;
            barrier.size = VK_WHOLE_SIZE;
            vkCmdPipelineBarrier(cmd, VK_PIPELINE_STAGE_TRANSFER_BIT, VK_PIPELINE_STAGE_HOST_BIT, 0,
                                 0, nullptr, 1, &barrier, 0, nullptr);
        }
        check(vkEndCommandBuffer(cmd), "Ending a command buffer");
    }

    ~Impl() {
        if (device) {
            vkDeviceWaitIdle(device);
            for (GpuMesh& m : meshes) {
                destroy_buffer(m.vertices);
                destroy_buffer(m.indices);
            }
            for (Frame& f : frames) {
                destroy_buffer(f.ubo);
                destroy_buffer(f.overlay);
                if (f.fence) vkDestroyFence(device, f.fence, nullptr);
                if (f.image_ready) vkDestroySemaphore(device, f.image_ready, nullptr);
            }
            destroy_target();
            if (descriptor_pool) vkDestroyDescriptorPool(device, descriptor_pool, nullptr);
            if (command_pool) vkDestroyCommandPool(device, command_pool, nullptr);
            if (pipeline) vkDestroyPipeline(device, pipeline, nullptr);
            if (overlay_pipeline) vkDestroyPipeline(device, overlay_pipeline, nullptr);
            if (overlay_layout) vkDestroyPipelineLayout(device, overlay_layout, nullptr);
            if (pipeline_layout) vkDestroyPipelineLayout(device, pipeline_layout, nullptr);
            if (set_layout) vkDestroyDescriptorSetLayout(device, set_layout, nullptr);
            if (render_pass) vkDestroyRenderPass(device, render_pass, nullptr);
            if (allocator) vmaDestroyAllocator(allocator);
            vkDestroyDevice(device, nullptr);
        }
        if (surface) vkDestroySurfaceKHR(instance, surface, nullptr);
        if (instance) vkDestroyInstance(instance, nullptr);
    }
};

Renderer::Renderer(const RendererDesc& desc) : impl_(std::make_unique<Impl>()) {
    Impl& r = *impl_;
    r.offscreen = desc.offscreen;
    r.extent = {desc.width, desc.height};
    r.create_instance(desc);
    if (!r.offscreen) {
        if (!desc.create_surface) throw RenderError("A window target needs create_surface");
        r.create_surface = desc.create_surface;
        r.surface = reinterpret_cast<VkSurfaceKHR>(
            desc.create_surface(reinterpret_cast<VkInstance_T*>(r.instance)));
        if (!r.surface) throw RenderError("Creating the window surface failed");
    }
    r.pick_device();
    r.create_device();
    r.depth_format = r.pick_depth_format();
    if (r.offscreen)
        r.color_format = VK_FORMAT_R8G8B8A8_SRGB;
    else
        r.choose_swapchain_format();
    r.create_render_pass();
    r.create_target();
    r.create_pipeline();
    r.create_overlay_pipeline();
    r.create_frames();
}

Renderer::~Renderer() = default;

MeshId Renderer::upload_mesh(const MeshData& mesh) {
    Impl& r = *impl_;
    r.meshes.push_back({});
    const auto id = static_cast<MeshId>(r.meshes.size() - 1);
    replace_mesh(id, mesh);
    return id;
}

void Renderer::replace_mesh(MeshId id, const MeshData& mesh) {
    Impl& r = *impl_;
    if (id >= r.meshes.size()) throw RenderError("replace_mesh: no such mesh");
    GpuMesh& old = r.meshes[id];
    if (old.vertices.buffer) {
        vkDeviceWaitIdle(r.device);
        r.destroy_buffer(old.vertices);
        r.destroy_buffer(old.indices);
    }
    GpuMesh gpu;
    const VkDeviceSize vbytes = mesh.vertices.size() * sizeof(Vertex);
    const VkDeviceSize ibytes = mesh.indices.size() * sizeof(uint32_t);
    // Small static meshes live in host-visible memory for now; a staging upload to
    // device-local memory replaces this when real asset sizes arrive.
    gpu.vertices = r.create_buffer(vbytes, VK_BUFFER_USAGE_VERTEX_BUFFER_BIT, false);
    gpu.indices = r.create_buffer(ibytes, VK_BUFFER_USAGE_INDEX_BUFFER_BIT, false);
    std::memcpy(gpu.vertices.mapped, mesh.vertices.data(), vbytes);
    std::memcpy(gpu.indices.mapped, mesh.indices.data(), ibytes);
    vmaFlushAllocation(r.allocator, gpu.vertices.allocation, 0, VK_WHOLE_SIZE);
    vmaFlushAllocation(r.allocator, gpu.indices.allocation, 0, VK_WHOLE_SIZE);
    gpu.index_count = static_cast<uint32_t>(mesh.indices.size());
    r.meshes[id] = gpu;
}

bool Renderer::render_frame(const Camera& camera, const Light& light,
                            std::span<const DrawItem> draws, const glm::vec4& clear_color) {
    Impl& r = *impl_;
    Impl::Frame& f = r.frames[r.frame_index];
    check(vkWaitForFences(r.device, 1, &f.fence, VK_TRUE, UINT64_MAX), "Waiting for a frame");

    uint32_t image = 0;
    if (!r.offscreen) {
        const VkResult acquired = vkAcquireNextImageKHR(r.device, r.swapchain, UINT64_MAX,
                                                        f.image_ready, VK_NULL_HANDLE, &image);
        if (acquired == VK_ERROR_OUT_OF_DATE_KHR) {
            r.recreate_target();
            return false;
        }
        if (acquired == VK_ERROR_SURFACE_LOST_KHR) {
            r.recreate_surface();
            return false;
        }
        if (acquired != VK_SUBOPTIMAL_KHR) check(acquired, "Acquiring a swapchain image");
    }
    check(vkResetFences(r.device, 1, &f.fence), "Resetting a fence");

    FrameData data{camera.projection * camera.view, glm::vec4(light.direction, 0.0f),
                   glm::vec4(to_linear(light.color), 1.0f),
                   glm::vec4(to_linear(light.ambient), 1.0f)};
    std::memcpy(f.ubo.mapped, &data, sizeof(data));
    vmaFlushAllocation(r.allocator, f.ubo.allocation, 0, VK_WHOLE_SIZE);

    r.prepare_overlay(f);
    check(vkResetCommandBuffer(f.cmd, 0), "Resetting a command buffer");
    r.record(f.cmd, r.framebuffers[r.offscreen ? 0 : image], draws, clear_color, f.set, f);

    VkPipelineStageFlags wait_stage = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
    VkSubmitInfo submit{VK_STRUCTURE_TYPE_SUBMIT_INFO};
    submit.commandBufferCount = 1;
    submit.pCommandBuffers = &f.cmd;
    if (!r.offscreen) {
        submit.waitSemaphoreCount = 1;
        submit.pWaitSemaphores = &f.image_ready;
        submit.pWaitDstStageMask = &wait_stage;
        submit.signalSemaphoreCount = 1;
        submit.pSignalSemaphores = &r.render_done[image];
    }
    check(vkQueueSubmit(r.queue, 1, &submit, f.fence), "Submitting a frame");

    if (r.offscreen) {
        check(vkWaitForFences(r.device, 1, &f.fence, VK_TRUE, UINT64_MAX), "Waiting for a frame");
    } else {
        VkPresentInfoKHR present{VK_STRUCTURE_TYPE_PRESENT_INFO_KHR};
        present.waitSemaphoreCount = 1;
        present.pWaitSemaphores = &r.render_done[image];
        present.swapchainCount = 1;
        present.pSwapchains = &r.swapchain;
        present.pImageIndices = &image;
        const VkResult presented = vkQueuePresentKHR(r.queue, &present);
        if (presented == VK_ERROR_OUT_OF_DATE_KHR || presented == VK_SUBOPTIMAL_KHR)
            r.recreate_target();
        else if (presented == VK_ERROR_SURFACE_LOST_KHR)
            r.recreate_surface();
        else
            check(presented, "Presenting a frame");
    }
    r.frame_index = (r.frame_index + 1) % kFramesInFlight;
    return true;
}

void Renderer::set_overlay(std::vector<OverlayLine> lines) {
    impl_->overlay_lines = std::move(lines);
}

void Renderer::resize(uint32_t width, uint32_t height) {
    if (width == 0 || height == 0) return;  // minimised
    impl_->extent = {width, height};
    impl_->recreate_target();
}

std::vector<uint8_t> Renderer::read_pixels() {
    Impl& r = *impl_;
    if (!r.offscreen) throw RenderError("read_pixels needs an offscreen renderer");
    vmaInvalidateAllocation(r.allocator, r.readback.allocation, 0, VK_WHOLE_SIZE);
    const auto* src = static_cast<const uint8_t*>(r.readback.mapped);
    return {src, src + size_t(r.extent.width) * r.extent.height * 4};
}

void Renderer::recreate_surface() {
    if (!impl_->offscreen) impl_->recreate_surface();
}

uint32_t Renderer::width() const {
    return impl_->extent.width;
}
uint32_t Renderer::height() const {
    return impl_->extent.height;
}
std::string Renderer::device_name() const {
    return impl_->gpu_props.deviceName;
}

glm::mat4 relative_to(const glm::dmat4& world, const glm::dvec3& origin) {
    glm::dmat4 m = world;
    m[3] -= glm::dvec4(origin, 0.0);  // done in double: only the small difference becomes float
    return glm::mat4(m);
}

glm::mat4 perspective(float fov_y_radians, float aspect, float near_plane, float far_plane) {
    glm::mat4 p = glm::perspectiveRH_ZO(fov_y_radians, aspect, near_plane, far_plane);
    p[1][1] *= -1.0f;  // Vulkan's clip space has y pointing down
    return p;
}

}  // namespace midgard::render
